    /// <summary>
    /// MPJ_3735_Aged Balance
    /// </summary>
    /// <param name = "_custTable">
    /// get CustTable record
    /// </param>
    /// <returns>
    /// return outstanding credit limit percent 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display Percent getMETCreditLimitOutstanding(CustTable _custTable)
    {
        percent                     metCreditLimitOutstanding;
        CustAging                   metCustaging;
        CustAgingLegalEntityView    metCustAgingLegalEntityView;
        
        select firstonly SumOfAmountDueMst, SumOfCreditLimitMst 
            from    metCustAgingLegalEntityView
            exists join metCustaging
            where   metCustaging.RecId      == metCustAgingLegalEntityView.CustAging
            &&      metCustaging.CustTable  == _custTable.AccountNum;

        if(metCustAgingLegalEntityView.SumOfCreditLimitMst == 0)
        {
            metCreditLimitOutstanding = 0;
        }
        
        if(metCustAgingLegalEntityView.SumOfCreditLimitMst != 0)
        {
            metCreditLimitOutstanding = ((metCustAgingLegalEntityView.SumOfAmountDueMst / metCustAgingLegalEntityView.SumOfCreditLimitMst) *100);
        }
        
        return metCreditLimitOutstanding;
    }

    /// <summary>
    /// MPJ_1663_Amex balance to be added to Aged Balance Inquiry
    /// </summary>
    /// <param name = "_custTable">
    /// get cust table record
    /// </param>
    /// <returns>
    /// return AMEXBalance
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    static display METAMEXBalance getMETamexbalance(CustTable _custTable)
    {
        METCustTable    metCustTable;

        select firstonly AccountNum, AMEXBalance from metCustTable
            where  metCustTable.AccountNum  == _custTable.AccountNum;

        return metCustTable.AMEXBalance;
    }

    /// <summary>
    /// Display Remaing amount
    /// </summary>
    /// <param name = "_custTable">get cust table record</param>
    /// <returns>Remaining Amount</returns>
    static display AmountMST getRemainAmountMST(CustTable _custTable)
    {
        CustTrans custTrans;
        AmountMST remainAmountMST;

        while select AmountMST, ExchAdjustment, SettleAmountMST from custTrans
            where CustTrans.accountNum == _custTable.accountNum
            &&    CustTrans.TransType  == LedgerTransType::Payment
        {
            remainAmountMST = custTrans.AmountMST + custTrans.ExchAdjustment - custTrans.SettleAmountMST + remainAmountMST;
        }

        return remainAmountMST;
    }

