/// <summary>
/// Code added by TCS to make value for Exclude interest charge to YES
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(CustTable), DataEventType::Inserting)]
public static void CustTable_onInserting(Common sender, DataEventArgs e)
{
    CustTable cTable = sender as CustTable;
    cTable.CustExcludeInterestCharges = NoYes::Yes;
}

    /// <summary>
    /// CB503_CustomerNumbering
    /// Retrieves the numbersequenceformhandler that can be used in the form creation of this entity
    /// to generate the numbersequence related field
    /// </summary>
    /// <param name="callerForm">
    /// The form that will be using this numbersequenceformhandler to create this entity
    /// </param>
    /// <param name="numberSequenceDatasource">
    /// The datasource that contains this entity on the creation form
    /// </param>
    /// <returns>
    /// the numbersequenceformhandler that can be used in the form creation of this entity
    /// </returns>
    public static NumberSeqFormHandler getNumberSeqFormHandler(ObjectRun callerForm, FormDataSource numberSequenceDatasource)
    {
        NumberSeqFormHandler    numberSeqFormHandler;
        FormRun callerFormRun = callerForm as FormRun;
        FormDataSource custDatasource = callerFormRun.dataSource(1);
        CustTable custTable = custDatasource.cursor();
        CustGroup custGroup = CustGroup::find(custTable.CustGroup);
        METBusinessUnit businessUnit;
        
        if (!numberSeqFormHandler || numberSeqFormHandler.parmNumberSequenceId() != CustParameters::numRefCustAccount().NumberSequenceId)
        {
            numberSeqFormHandler = NumberSeqFormHandler::newForm(CustParameters::numRefCustAccount().NumberSequenceId,
                                                                    callerForm,
                                                                    numberSequenceDatasource,
                                                                    fieldNum(CustTable, AccountNum));
        }
        
        numberSeqFormHandler = next getNumberSeqFormHandler(callerForm, numberSequenceDatasource);

        //CB503_CustomerNumbering, getting Number sequence from custom setup if enabled
        if (custGroup.METEnableCustNumbering)
        {
            businessUnit    = METBusinessUnit::findRecId(custTable.METBusinessUnitTableRefRecId);
            if (businessUnit.RecId)
            {
                if (!numberSeqFormHandler || numberSeqFormHandler.parmNumberSequenceId() != businessUnit.NumberSequenceId)
                {
                    numberSeqFormHandler = NumberSeqFormHandler::newForm(businessUnit.NumberSequenceId,
                                                                        callerForm,
                                                                        numberSequenceDatasource,
                                                                        fieldNum(CustTable, AccountNum));
                }
            }
        }
         
        return numberSeqFormHandler;
    }

    /// <summary>
    /// Verifies or sets additional field values based on the modified field.
    /// </summary>
    /// <param name = "_fieldId">The field ID of the field that was modified.</param>
    [Hookable(false)]
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(CustTable, CredManAccountStatusId) :
                this.sendCustomerStatusBusinessEvent();
                break;
        }
    }

/// <summary>
/// sends a business event on update of the customer account status
/// </summary>
internal void sendCustomerStatusBusinessEvent()
{
    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METCustomerStatusChangeBusinessEvent)))
    {
        CustTable custTable = this as CustTable;
        METCustomerStatusChangeBusinessEvent::newFromCustTable(custTable).send();
    }
}

/// <summary>
/// does an Exytract number sequence exist?
/// </summary>
/// <param name = "_accountNum">Account number</param>
/// <returns>true if exists</returns>
public static boolean metExtractNumSeqExist(CustAccount _accountNum)
{
    return _accountNum
    && (select firstOnly RecId
        from custTable
        where CustTable.AccountNum == _accountNum).RecId != 0;
}

    /// <summary>
    /// CB503_CustomerNumbering + Bug 238049: CB393 - Create an IGA customer for CCD_5
    /// get the customer number sequence
    /// </summary>
    /// <param name = "_metBusinessUnitRecId"Business unit></param>
    /// <param name = "_custAccount">existingNumberSeq</param>
    /// <returnsNumber sequence></returns>
    public static CustAccount metGetCustomerNumSeqRec(RefRecId _metBusinessUnitRecId, CustAccount       _custAccount = "")
    {
        NumberSequenceCode      numberSequence;
        NumberSequenceCode      numberSeq;
        METBusinessUnit         metBusinessUnit     = METBusinessUnit::findRecId(_metBusinessUnitRecId);
        RefRecId                numberseqcust       = metBusinessUnit.NumberSequenceId;
        Integer                 businessPrefixValue = metBusinessUnit.BusinessPrefix;
        NumberSequenceTable     numberseqTable      = NumberSequenceTable::find(numberseqcust);
        METDigitLogicCheck      digitLogicCheck     = metBusinessUnit.CheckDigitLogic;
        int                     checkDigit;

        if (metBusinessUnit.RecId)
        {
            // Bug 238049: CB393 - Create an IGA customer for CCD_5 - Start
            if (_custAccount)
            {
                numberSeq = _custAccount;
            }
            else
            {
                numberSeq = NumberSeq::newGetNumFromId(numberseqTable.RecId).num();
            }
            // Bug 238049: CB393 - Create an IGA customer for CCD_5 - End

            if (metBusinessUnit.EnableStatePrefix == NoYes::Yes)
            {
                numberSequence = int2Str(businessPrefixValue) + metBusinessUnit.StatePrefixStr + numberSeq;
            }
            else
            {
                numberSequence = int2Str(businessPrefixValue) + numberSeq;
            }

            switch(digitLogicCheck)
            {
                case METDigitLogicCheck::PECCD1 :
                    checkDigit = METCheckDigitLogicHelper::getCheckDigit_One(numberSeq);
                    break;

                case METDigitLogicCheck::PECCD2 :
                    checkDigit = METCheckDigitLogicHelper::getCheckDigit_Two(numberSequence);
                    break;

                case METDigitLogicCheck::PECCD5:
                    checkDigit = METCheckDigitLogicHelper::checkDigit_Five(numberSeq);
                    break;

                case METDigitLogicCheck::ZZCD02 :
                    checkDigit = METCheckDigitLogichelper::getCheckDigitZZCD02(numberSequence);
                    break;
            }
            
            numberSequence =  numberSequence + int2Str(checkDigit);
        }
        if(strLen(numberSequence) > 8)
        {
            throw warning("@MET:METCustomerNumCheckDigits");
        }
        return numberSequence;
    }

    /// <summary>
