    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Validates if account status can be modified.
    /// </summary>
    /// <returns>True, if account status can be modified; otherwise, false.</returns>
    public boolean metValidateAccountStatusModified()
    {
        boolean ret;

        ret = (this.metValidateABNVerifiedDate() && this.metValidateRegistrationIdVerifiedDate());

        return ret;
    }

/// <summary>
///  CB756_ValidationOfABNToATOSystem.
///  Checks if Verified number is required or not.
/// </summary>
/// <returns>True, if verified number is required; otherwise, false.</returns>
public boolean metAccountStatusVerifiedNumberRequired()
{
    return (select firstonly RecId from credManAccountStatusTable
                where credManAccountStatusTable.CustAccountStatusId == this.CredManAccountStatusId
                &&    credManAccountStatusTable.METABNValidation    == METABNValidationType::VerifiedNumberRequired).RecId != 0;
}

    /// <summary>
    ///  CB756_ValidationOfABNToATOSystem.
    ///  Validates ABN verified date.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    public boolean metValidateABNVerifiedDate()
    {
        boolean                   ret = true;

        if (strLen(this.VATNum) > 0
                && this.metAccountStatusVerifiedNumberRequired())
        {
            if (this.metGetABNVerifiedDate() == dateNull())
            {
                ret = checkFailed(strFmt("@MET:ABNVerifiedDateError", this.AccountNum, this.CredManAccountStatusId));
            }
        }

        return ret;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Validates Registration Id verified date.
    /// </summary>
    /// <returns>True, if valid; otherwise, false.</returns>
    public boolean metValidateRegistrationIdVerifiedDate()
    {
        DirPartyLocation                     dirPartyLocation;
        TaxRegistration                      taxRegistration;
        TaxRegistrationType                  taxRegistrationType;
        TaxRegistrationTypeApplicabilityRule taxRegistrationTypeApplicabilityRule;
        TaxRegistrationTypeCountryId         countryRegionId;
        TransDate                            transDate;
        boolean                              ret = true;
        
        if (this.metAccountStatusVerifiedNumberRequired())
        {
            transDate        = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            countryRegionId  = CompanyInfo::find().postalAddress().CountryRegionId;
        
            select firstOnly validTimeState(transDate) RegistrationNumber from taxRegistration
                join RecId from taxRegistrationTypeApplicabilityRule
                    where taxRegistration.TaxRegistrationTypeApplicabilityRule       == taxRegistrationTypeApplicabilityRule.RecId
                    &&    taxRegistrationTypeApplicabilityRule.METValidateABNWithATO == NoYes::Yes
                    &&    taxRegistrationTypeApplicabilityRule.CountryRegionId       == countryRegionId
                    &&    taxRegistration.METVerifiedDate                            == dateNull()
                join TaxRegstrationType from taxRegistrationType
                    where taxRegistrationType.RecId == taxRegistrationTypeApplicabilityRule.TaxRegistrationType
                exists join dirPartyLocation
                    where taxRegistration.DirPartyLocation == dirPartyLocation.RecId
                       && dirPartyLocation.IsPrimary       == NoYes::Yes
                       && dirPartyLocation.Party           == this.Party;
  
            if (taxRegistration.RegistrationNumber)
            {
                ret = checkFailed(strFmt("@MET:RegistationIdVerifiedDateError", this.AccountNum,
                                                                                this.CredManAccountStatusId,
                                                                                taxRegistrationType.TaxRegstrationType,
                                                                                taxRegistration.RegistrationNumber));
            }

        }
        
        return ret;
    }

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip
    /// If customer is TOTE customer based on the invent parameters METAttributeIdentifiers Tote attribute records
    /// </summary>
    /// <param name = "_custAccount"Customer account</param>
    /// <param name = "_dataAreaId">Data area id</param>
    /// <returns>True if tote customer; otherzise, false.</returns>
    public static boolean METIsToteCustomer(CustAccount _custAccount, DataAreaId _dataAreaId)
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == _custAccount
            && instanceValue.CustomerDataAreaId == _dataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeValueText == attributeValuesTable.TextValue
                    &&  attributeIdentifiers.AttributeValueText != ''
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }

    /// <summary>
    /// To check if the customer has Tote type (attribute type) defined under inventory parameters - Metcash - Attribute identifiers
    /// </summary>
    /// <param name = "_custAccount"Customer account</param>
    /// <param name = "_dataAreaId">Data area id</param>
    /// <returns>True if the customer has Tote type (attribute type); otherwise, false.</returns>
    public static boolean METHasToteAttributeType(CustAccount _custAccount, DataAreaId _dataAreaId)
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == _custAccount
            && instanceValue.CustomerDataAreaId == _dataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }

    /// <summary>
    /// Cb272 Invoicing - VM 
    /// Fetch the text valud of the customer attribute
    /// </summary>
    /// <param name = "_custId">_custId</param>
    /// <param name = "_name">_name</param>
    /// <returns>AttributeValueText</returns>
    public AttributeValueText metGetCustomerAttribute(AccountNum _custId, Name _name)
    {
        ecoResValue ecoResValue;
        ecoResAttributeValue ecoResAttributeValue;
        ecoResAttribute ecoResAttribute;
        ecoResAttributeType ecoResAttributeType;
        ecoResInstanceValue ecoResInstanceValue;
        CustomerInstanceValue customerInstanceValue;
        EcoResTextValue ecoResTextValue;

        select firstonly recId from ecoResAttributeValue
            join RecId from ecoResAttribute
                where ecoResAttributeValue.Attribute == ecoResAttribute.RecId
            join RecId from ecoResAttributeType
                where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
            join ecoResInstanceValue
                where ecoResAttributeValue.InstanceValue == ecoResInstanceValue.RecId
            join AccountNum,recId from customerInstanceValue
                where customerInstanceValue.RecId == ecoResInstanceValue.RecId
            join RecId from ecoResValue
                where ecoResAttributeValue.Value == ecoResValue.RecId && customerInstanceValue.AccountNum == _custId
            join textvalue from ecoResTextValue
                where ecoResTextValue.RecId == ecoResValue.RecId
                    && ecoResAttribute.Name == _name;

        return ecoResTextValue.textvalue;
    }

    /// <summary>
    /// Validates the customer account status field for updation.
    /// </summary>
    /// <param name = "_formRun">Formrun instance</param>
    /// <param name = "_custTableDS">CustTable datasource</param>
    /// <returns>A boolean value</returns>
    internal boolean validateCustomerAccountStatus(FormRun _formRun, FormDataSource _custTableDS = null)
    {
        const str CustTableStr = 'CustTable';
        const str METCustTableStr = 'METCustTable';
        const str DirPartyTableStr = 'DirPartyTable';
        boolean ret = true;
        boolean isUpdate = true;
        
        FormRun formRun = _formRun;

        FormDataSource custTableDS;
        FormDataSource metCustTableDS;
        FormDataSource dirPartyTableDs;

        if (_custTableDS != null)
        {
            custTableDS = _custTableDS;
        }
        else
        {
            custTableDS = formRun.dataSource(formDataSourceStr(CustTable, CustTable));
        }
        
        metCustTableDS = formRun.dataSource(formDataSourceStr(CustTable, METCustTable));
        dirPartyTableDs = formRun.dataSource(formDataSourceStr(CustTable, DirPartyTable));
        
        CustTable custTable = custTableDS.cursor();
        METCustTable metCustTable = metCustTableDS.cursor();
        DirPartyTable dirPartyTable = dirPartyTableDs.cursor();

        if (custTable.CustGroup)
        {
            METTableFieldNames fieldNames;

            while select TableFieldName, FieldName, CustTableName from fieldNames
                where fieldNames.CustGroup == custTable.CustGroup
                && fieldNames.CustAccountStatusId == custTable.CredManAccountStatusId
            {
                Common common;
                FieldId fieldId;

                if (enum2Str(fieldNames.CustTableName) == CustTableStr)
                {
                    common = custTable;
                    fieldId = fieldName2Id(custTable.TableId, fieldNames.FieldName);
                }
                else if (enum2Str(fieldNames.CustTableName) == METCustTableStr)
                {
                    common = metCustTable;
                    fieldId = fieldName2Id(metCustTable.TableId, fieldNames.FieldName);
                }
                else if (enum2Str(fieldNames.CustTableName) == DirPartyTableStr)
                {
                    common = dirPartyTable;
                    fieldId = fieldName2Id(dirPartyTable.TableId, fieldNames.FieldName);
                }

                if (fieldId && !common.(fieldId))
                {
                    ret = checkFailed(strFmt("@MET:MandatoryFieldErr", fieldNames.TableFieldName));
                    isUpdate = false;
                }
            }

            METMandatoryCustAddrInfo addrInfo;

            while select Purpose from addrInfo
                where addrInfo.CustGroup == custTable.CustGroup
                && addrInfo.CustAccountStatusId == custTable.CredManAccountStatusId
            {
                ret = this.isCustomerPostalAddressExists(custTable.Party, addrInfo.Purpose);

                if (!ret)
                {
                    isUpdate = false;
                }
            }

            METMandatoryCustContactInfo contactInfo;

            while select Purpose, Type from contactInfo
                where contactInfo.CustGroup == custTable.CustGroup
                && contactInfo.CustAccountStatusId == custTable.CredManAccountStatusId
            {
                ret = this.isCustomerContactInfoExists(custTable.Party, contactInfo.Purpose, contactInfo.Type);

                if (!ret)
                {
                    isUpdate = false;
                }
            }
        }

        if (custTable.CredManAccountStatusId == METConstants::custAccountStatusClosed)
        {
            CustTransOpen metCustTransOpen;
            CustTrans metCustTrans;

            select firstonly RecId from metCustTransOpen
                where metCustTransOpen.AccountNum == custTable.AccountNum;

            select sum(AmountMST) from metCustTrans
                where metCustTrans.AccountNum == custTable.AccountNum;

            if (metCustTransOpen.RecId && metCustTrans.AmountMST == 0)
            {
                ret = false;
                error ('@MET:METCustAccountStatusValidation');
            }
        }

        if (ret && isUpdate)
        {
            ret = custTable.metValidateAccountStatusModified();
            isUpdate = ret;
        }

        return isUpdate;
    }

    /// <summary>
    /// Returns true if customer postal address exists, otherwise false.
    /// </summary>
    /// <param name = "_party">Customer party id</param>
    /// <param name = "_purpose">Purpose</param>
    /// <returns>A boolean value</returns>
    private boolean isCustomerPostalAddressExists(RecId _party, LogisticsLocationRoleName _purpose)
    {
        boolean ret = true;
        DirPartyLocation partyLocation;
        LogisticsPostalAddress postalAddress;

        LogisticsLocationRoleName purposeFilter = strFmt('*%1*', _purpose);

        select firstonly RecId from postalAddress
        exists join PostalAddressRoles from partyLocation
            where partyLocation.Location == postalAddress.Location
            && partyLocation.Party == _party
            && partyLocation.PostalAddressRoles like purposeFilter;

        if (!postalAddress.RecId)
        {
            ret = checkFailed(strFmt("@MET:NoAddrErr", _purpose));
        }

        return ret;
    }

    /// <summary>
    /// Returns true if customer contact exists, otherwise false.
    /// </summary>
    /// <param name = "_party">Customer party id</param>
    /// <param name = "_purpose">Purpose</param>
    /// <param name = "_type">Type</param>
    /// <returns>A boolean value</returns>
    private boolean isCustomerContactInfoExists(RecId _party, LogisticsLocationRoleName _purpose, LogisticsElectronicAddressMethodType _type)
    {
        boolean ret = true;

        DirPartyLocation partyLocation;
        LogisticsElectronicAddress electronicAddress;
        LogisticsLocationRoleName purposeFilter = strFmt('*%1*', _purpose);

        select firstonly RecId from electronicAddress
            where electronicAddress.Type == _type
            && electronicAddress.ElectronicAddressRoles like purposeFilter
        exists join partyLocation
            where partyLocation.Location == electronicAddress.Location
            && partyLocation.Party == _party;

        if (!electronicAddress.RecId)
        {
            ret = checkFailed(strFmt("@MET:NoContactInfoErr", _purpose, _type));
        }

        return ret;
    }

    /// <summary>
    /// Initializing the account status from the AR parameters.
    /// </summary>
    public void initValue()
    {

        CustParameters          custParameter   = CustParameters::find();

        next initValue();

        if (!this.CredManAccountStatusId)
        {
            this.CredManAccountStatusId = CustParameters::find().METCredManAccountStatusId;
        }

        // Update the trading date on insertion of records
        if (custParameter.METCredManAccountStatusId)
        {
            this.METTradingAccountStatusDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        }
    }

    /// <summary>
    /// Get delivery address of customer
    /// </summary>
    /// <returns>LogisticsAddressing</returns>
    public LogisticsAddressing metGetDeliveryaddress()
    {
        LogisticsPostalAddress  logisticsPostalAddress;
        DirPartyLocation dirPartyLocation;

        select firstonly address from logisticsPostalAddress
            order by dirPartyLocation.IsPrimary desc
            join dirPartyLocation 
                where dirPartyLocation.Location == logisticsPostalAddress.Location && dirPartyLocation.Party == this.party && dirPartyLocation.IsRoleDelivery == 1;

        return LogisticsPostalAddress.Address;
    }

    /// <summary>
    /// Checks WET Tax Exempt Tax group.
    /// </summary>
    private void metCheckWETTaxExempt()
    {
        if (this.TaxGroup)
        {
            METCustTable metCustTable;
            METWETTaxGroupParameters   metWETParams;

            select firstonly WETExempt from metCustTable
                where metCustTable.AccountNum == this.AccountNum;

            // Only show warning when there are WET tax group parameters configured
            // For BUG 351090  
            //  Only call warning("@MET:WETExemptTaxGroupWarning") when:
            //    1. the customer WETExempt flag is set,
            //    2. the METWETTaxGroupParameters table is not empty, and
            //    3. the customer's TaxGroup is not present in METWETTaxGroupParameters::exist.

            select firstonly RecId from metWETParams;

            if (metCustTable.WETExempt && metWETParams.RecId && !METWETTaxGroupParameters::exist(this.TaxGroup))
            {
                warning("@MET:WETExemptTaxGroupWarning");
            }
        
        }
    }

    public Boolean metGetCustomerBooleanAttribute(AccountNum _custId, Name _name)
    {
        ecoResValue ecoResValue;
        ecoResAttributeValue ecoResAttributeValue;
        ecoResAttribute ecoResAttribute;
        ecoResAttributeType ecoResAttributeType;
        ecoResInstanceValue ecoResInstanceValue;
        CustomerInstanceValue customerInstanceValue;
        EcoResTextValue ecoResTextValue;
        EcoResBooleanValue ecoResBooleanValue;

        select firstonly recId from ecoResAttributeValue
            join RecId from ecoResAttribute
                where ecoResAttributeValue.Attribute == ecoResAttribute.RecId
            join RecId from ecoResAttributeType
                where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
            join ecoResInstanceValue
                where ecoResAttributeValue.InstanceValue == ecoResInstanceValue.RecId
            join AccountNum,recId from customerInstanceValue
                where customerInstanceValue.RecId == ecoResInstanceValue.RecId
            join RecId from ecoResValue
                where ecoResAttributeValue.Value == ecoResValue.RecId && customerInstanceValue.AccountNum == _custId
            join BooleanValue from ecoResBooleanValue
                where ecoResBooleanValue.RecId == ecoResValue.RecId
                    && ecoResAttribute.Name == _name;

        return ecoResBooleanValue.BooleanValue;
    }
